import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry gelu_tanh_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 size
)
{
    .reg .pred   %p1;
    .reg .b32    %r_idx, %r_size, %r_cta, %r_ntid, %r_tid;
    .reg .b64    %rd_in_param, %rd_out_param, %rd_in, %rd_out, %rd_off, %rd_addr_in, %rd_addr_out;

    .reg .f32    %f_x, %f_x2, %f_x3, %f_inner, %f_z, %f_t, %f_tmp, %f_res;

    // Load parameters
    ld.param.u64 %rd_in_param, [in_ptr];
    ld.param.u64 %rd_out_param, [out_ptr];
    ld.param.u32 %r_size, [size];

    // Convert to global addresses
    cvta.to.global.u64 %rd_in, %rd_in_param;
    cvta.to.global.u64 %rd_out, %rd_out_param;

    // Compute linear thread index
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_cta, %ctaid.x;
    mov.u32 %r_ntid, %ntid.x;
    mad.lo.s32 %r_idx, %r_cta, %r_ntid, %r_tid;

    // Bounds check
    setp.ge.u32 %p1, %r_idx, %r_size;
    @%p1 bra DONE;

    // Byte offset and addresses
    mul.wide.u32 %rd_off, %r_idx, 4;
    add.s64 %rd_addr_in, %rd_in, %rd_off;
    add.s64 %rd_addr_out, %rd_out, %rd_off;

    // Load x
    ld.global.f32 %f_x, [%rd_addr_in];

    // x^3
    mul.rn.f32 %f_x2, %f_x, %f_x;
    mul.rn.f32 %f_x3, %f_x2, %f_x;

    // inner = x + 0.044715 * x^3
    mov.f32 %f_tmp, 0.044715;
    fma.rn.f32 %f_inner, %f_tmp, %f_x3, %f_x;

    // z = sqrt(2/pi) * inner, sqrt(2/pi) ~ 0.7978845834732056
    mov.f32 %f_tmp, 0.7978845834732056;
    mul.rn.f32 %f_z, %f_tmp, %f_inner;

    // t = tanh(z)
    tanh.approx.f32 %f_t, %f_z;

    // result = 0.5 * (x + x * t) = 0.5 * fma(x, t, x)
    fma.rn.f32 %f_tmp, %f_x, %f_t, %f_x;
    mov.f32 %f_z, 0.5;
    mul.rn.f32 %f_res, %f_z, %f_tmp;

    // Store
    st.global.f32 [%rd_addr_out], %f_res;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("gelu_tanh_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor):
        # Assumes x is float32 CUDA tensor; matches reference behavior for provided inputs.
        out = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        N = x.numel()
        threads = 256
        blocks = (N + threads - 1) // threads

        module = _get_ptx_module()
        module.launch(
            "gelu_tanh_kernel",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[x, out, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

